-- Daily challenges for 2026-11-22: two new themes, 365 to-dos each (added on 2026-11-25 to fill a missed day).
-- Generated by tools/challenges_sql.py finding-calm-before-big-moments spending-time-among-trees. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('finding-calm-before-big-moments', 'Finding Calm Before Big Moments', 'For anyone whose nerves rise before an interview, a presentation, an appointment or a big conversation. Each day is one small way to prepare, steady your body and mind, and walk into important moments feeling a little calmer.', 'Anxiety', 365, array['Anxiety', 'Stress']::text[], 1, '2026-11-22T17:00:00+00:00'::timestamptz),
  ('spending-time-among-trees', 'Spending Time Among Trees', 'For anyone who feels steadier with a little green around them. Each day is one small way to notice, visit, learn about and care for the trees near you, from a single street tree to a park or woods, in every season.', 'Grounding', 365, array['Grounding', 'Mindfulness']::text[], 1, '2026-11-22T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('finding-calm-before-big-moments', 'spending-time-among-trees');

